"""Atomic local checkpoints, guarded by a single-writer process lock."""
from contextlib import contextmanager
import json
import os
from pathlib import Path
import tempfile


class RecoveryRequired(RuntimeError):
    """A tool may have executed; an operator must reconcile its outcome."""


class CheckpointStore:
    def __init__(self, path):
        self.path = Path(path)

    @contextmanager
    def locked(self):
        # The local runtime targets Linux/WSL; never silently omit locking.
        import fcntl
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.with_suffix(self.path.suffix + '.lock').open('a') as handle:
            try:
                fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise RuntimeError('This checkpoint is already in use.') from exc
            try:
                yield
            finally:
                fcntl.flock(handle, fcntl.LOCK_UN)

    def is_active(self):
        """Probe the OS lock, not a stale PID or the existence of a lock file."""
        import fcntl
        path = self.path.with_suffix(self.path.suffix + '.lock')
        if not path.exists():
            return False
        with path.open('r') as handle:
            try:
                fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                return True
            fcntl.flock(handle, fcntl.LOCK_UN)
            return False

    def read(self):
        return json.loads(self.path.read_text(encoding='utf-8'))

    def write(self, state):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, name = tempfile.mkstemp(dir=self.path.parent, prefix='.checkpoint-')
        try:
            with os.fdopen(fd, 'w', encoding='utf-8') as handle:
                json.dump(state, handle, ensure_ascii=False)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(name, self.path)
            directory = os.open(self.path.parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            if os.path.exists(name):
                os.unlink(name)

cardinal_agent/agent/registry.py:
"""Tool registration, side-effect-free validation, and contained execution."""

from copy import deepcopy

from jsonschema import Draft202012Validator

from cardinal_agent.types import ToolResult, ToolSpec


class ToolRegistry:
    """Keep tool lookup separate from executing a validated call."""

    def __init__(self, tools: list[ToolSpec]):
        if len({tool.name for tool in tools}) != len(tools):
            raise ValueError('Duplicate tool names are not allowed.')
        for tool in tools:
            if (tool.execute_with_id is None) != (tool.lookup_result is None):
                raise ValueError(f'{tool.name}: execute_with_id and lookup_result must be supplied together.')
        self.tools = {tool.name: tool for tool in tools}
        self._validators = {
            name: Draft202012Validator(deepcopy(tool.parameters))
            for name, tool in self.tools.items()
        }

    def schemas(self) -> list[dict]:
        # Do not expose mutable schemas to callers or include Python functions.
        return [
            {"name": tool.name, "description": tool.description,
             "parameters": deepcopy(self._validators[tool.name].schema)}
            for tool in self.tools.values()
        ]

    def validate(self, name: str, args: dict) -> ToolResult | None:
        try:
            if name not in self.tools:
                return ToolResult("unknown_tool", f"Unknown tool: {name}")
            self._validators[name].validate(args)
        except Exception as exc:
            return ToolResult("invalid_args", str(exc) or type(exc).__name__)
        return None

    def execute(self, name: str, args: dict, *, operation_id: str | None = None) -> ToolResult:
        error = self.validate(name, args)
        if error is not None:
            return error
        try:
            spec = self.tools[name]
            if operation_id is not None and spec.execute_with_id is not None:
                value = spec.execute_with_id(deepcopy(args), operation_id)
            else:
                value = spec.fn(**args)
            return ToolResult("ok", str(value))
        except Exception as exc:
            return ToolResult("tool_error", str(exc) or type(exc).__name__)

cardinal_agent/cardinal.py:
"""Shared definition of the Cardinal toolset.

``CARDINAL_TOOLS`` fixes, for each of the ten tools your agent offers, its
name, the JSON Schema of its arguments, and whether it is read-only. The
tests and the simulated users rely on these names and argument names, so do
not change them. You may register additional tools of your own.

Two things are left to you: the implementation of each tool, and its
description (the text the model reads to decide when and how to call it).
``cardinal_spec`` combines the two with the fixed parts into a ``ToolSpec``:

    spec = cardinal_spec("search_docs", "Search the ... (your text)", my_search_docs)
"""

from __future__ import annotations

import copy
from typing import Any, Callable

from cardinal_agent.types import ToolSpec


def _schema(properties: dict, required: list[str]) -> dict:
    return {
        "type": "object",
        "properties": properties,
        "required": required,
        "additionalProperties": False,
    }


_STRING = {"type": "string"}
_K = {"type": "integer", "minimum": 1, "default": 5}

# name -> {"parameters": JSON Schema, "read_only": bool}, in a fixed order.
# A tool that is not read-only needs the user's approval in confirm mode.
# ``remember`` writes only to the agent's own memory store, so it is marked
# read-only and does not need approval.
CARDINAL_TOOLS: dict[str, dict[str, Any]] = {
    "search_emails": {
        "parameters": _schema({"query": _STRING, "k": _K}, ["query"]),
        "read_only": True,
    },
    "read_email": {
        "parameters": _schema({"email_id": _STRING}, ["email_id"]),
        "read_only": True,
    },
    "email_qa": {
        "parameters": _schema({"question": _STRING}, ["question"]),
        "read_only": True,
    },
    "daily_digest": {
        "parameters": _schema(
            {"date": {"type": "string", "pattern": r"^\d{4}-\d{2}-\d{2}$"}}, ["date"]
        ),
        "read_only": True,
    },
    "search_docs": {
        "parameters": _schema({"query": _STRING, "k": _K}, ["query"]),
        "read_only": True,
    },
    "read_doc": {
        "parameters": _schema(
            {"doc_id": _STRING, "start_line": {"type": "integer", "minimum": 1, "default": 1}},
            ["doc_id"],
        ),
        "read_only": True,
    },
    "run_terminal": {
        "parameters": _schema({"cmd": _STRING}, ["cmd"]),
        "read_only": False,
    },
    "remember": {
        "parameters": _schema({"fact": _STRING}, ["fact"]),
        "read_only": True,
    },
    "recall": {
        "parameters": _schema({"query": _STRING}, ["query"]),
        "read_only": True,
    },
    "ask_user": {
        "parameters": _schema({"question": _STRING}, ["question"]),
        "read_only": True,
    },
}


def cardinal_spec(name: str, description: str, fn: Callable[..., Any]) -> ToolSpec:
    """Build the ``ToolSpec`` for the Cardinal tool called ``name``.

    ``description`` and ``fn`` are yours. The parameter schema and the
    read-only flag come from ``CARDINAL_TOOLS``. ``fn`` is called with the
    arguments as keyword arguments, for example ``fn(query="...", k=3)``.
    Optional arguments the model leaves out are not filled in, so give them
    default values in ``fn``'s signature (k=5, start_line=1).
    """
    if name not in CARDINAL_TOOLS:
        raise KeyError(f"{name!r} is not a Cardinal tool. Known tools: {', '.join(CARDINAL_TOOLS)}")
    entry = CARDINAL_TOOLS[name]
    return ToolSpec(
        name=name,
        description=description,
        parameters=copy.deepcopy(entry["parameters"]),
        fn=fn,
        read_only=entry["read_only"],
    )

"""A report tool whose effect and operation receipt share one SQLite transaction.

This demonstrates actual deduplication, not a generic promise that arbitrary
remote side effects can be made exactly-once by the harness.
"""
import json
from contextlib import closing
from pathlib import Path
import sqlite3

from cardinal_agent.types import ToolResult, ToolSpec


class ReportStore:
    def __init__(self, path):
        self.path = Path(path)
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with closing(sqlite3.connect(self.path)) as db, db:
            db.execute('CREATE TABLE IF NOT EXISTS reports '
                       '(operation_id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL)')

    def _result(self, row):
        return json.dumps(dict(zip(('operation_id', 'title', 'body'), row)), ensure_ascii=False)

    def execute(self, args, operation_id):
        with closing(sqlite3.connect(self.path)) as db, db:
            db.execute('INSERT OR IGNORE INTO reports VALUES (?, ?, ?)',
                       (operation_id, args['title'], args['body']))
            row = db.execute('SELECT * FROM reports WHERE operation_id = ?', (operation_id,)).fetchone()
            if row[1:] != (args['title'], args['body']):
                raise ValueError('Operation ID was already used with different arguments.')
            return self._result(row)

    def lookup(self, args, operation_id):
        with closing(sqlite3.connect(self.path)) as db, db:
            row = db.execute('SELECT * FROM reports WHERE operation_id = ?', (operation_id,)).fetchone()
        if row is None:
            return None
        if row[1:] != (args['title'], args['body']):
            raise ValueError('Operation arguments do not match the saved report.')
        return ToolResult('ok', self._result(row))

    def spec(self):
        def without_id(**args):
            raise ValueError('This tool requires a runtime-generated operation ID.')
        return ToolSpec('create_report', 'Save a report in a local transactional store.',
                        {'type': 'object', 'properties': {'title': {'type': 'string'},
                         'body': {'type': 'string'}}, 'required': ['title', 'body'],
                         'additionalProperties': False}, without_id,
                        execute_with_id=self.execute, lookup_result=self.lookup)

cardinal_agent/models/native.py:
"""Normalize native client tools without letting provider payloads execute code.

Transports are SDK create methods (or deterministic fakes), called with keyword
arguments. No credentials, SDK clients or executable functions are serialized.
"""
from copy import deepcopy
from dataclasses import dataclass, field
import json

from cardinal_agent.types import ToolCall


@dataclass
class NativeReply:
    text: str = ''
    tool_call: ToolCall | None = None
    provider_call_id: str | None = None
    usage: dict = field(default_factory=dict)


class NativeProtocolError(ValueError):
    pass


def _object(value):
    return value.model_dump() if hasattr(value, 'model_dump') else value


def _call(name, args, identifier):
    if not isinstance(name, str) or not name or not isinstance(args, dict):
        raise NativeProtocolError('Native tool call requires a name and object arguments.')
    if not isinstance(identifier, str) or not identifier:
        raise NativeProtocolError('Native tool call requires a provider call ID.')
    try:
        json.dumps(args, allow_nan=False)
    except (ValueError, TypeError) as exc:
        raise NativeProtocolError('Native arguments must be finite JSON values.') from exc
    return ToolCall(name, args)


def _usage(value):
    value = value or {}
    return {k: v for k, v in value.items() if isinstance(v, (int, float)) and not isinstance(v, bool)}


class _Adapter:
    native_tools = True

    def __init__(self, transport, model, *, max_tokens=2048, provider=None):
        self.transport = transport
        self.model = model
        self.max_tokens = max_tokens
        self.provider = provider or self.protocol_name

    def __call__(self, messages):
        # Text-only auxiliary calls (e.g. summaries) still use the same transport.
        reply = self.complete_native(messages, [])
        if reply.tool_call:
            raise NativeProtocolError('A text-only auxiliary call returned a tool invocation.')
        return reply.text

    def _history(self, messages):
        # Reconstruct pairs from trusted metadata, never from text that happens
        # to resemble a tool result. Compaction may leave orphaned evidence.
        results = {m['_harness_result']['id']: m for m in messages if '_harness_result' in m}
        paired = {m['_harness_call']['id'] for m in messages
                  if '_harness_call' in m and m['_harness_call']['id'] in results}
        for message in messages:
            call = message.get('_harness_call')
            result = message.get('_harness_result')
            if call and call['id'] in paired:
                yield 'pair', message, results[call['id']]
            elif result and result['id'] in paired:
                continue
            elif call:
                yield 'plain', {'role': 'assistant', 'content':
                    f"Earlier request to {call['name']} (result omitted from context)."}, None
            else:
                yield 'plain', message, None


class OpenAIChatAdapter(_Adapter):
    """OpenAI-compatible Chat Completions client tools (non-streaming)."""
    protocol_name = 'openai-chat'

    def complete_native(self, messages, schemas):
        history = []
        for kind, message, result in self._history(messages):
            if kind == 'pair':
                call = message['_harness_call']
                history.append({'role': 'assistant', 'content': call.get('text') or None,
                                'tool_calls': [{'id': call['id'], 'type': 'function', 'function':
                                    {'name': call['name'], 'arguments': json.dumps(call['args'], ensure_ascii=False)}}]})
                history.append({'role': 'tool', 'tool_call_id': call['id'], 'content': result['content']})
            else:
                history.append({'role': message['role'], 'content': message['content']})
        request = {'model': self.model, 'messages': history, 'max_tokens': self.max_tokens}
        if schemas:
            request.update(tools=[{'type': 'function', 'function': deepcopy(s)} for s in schemas],
                           parallel_tool_calls=False)
        response = _object(self.transport(**request))
        choices = response.get('choices', [])
        if len(choices) != 1 or choices[0].get('finish_reason') not in ('stop', 'tool_calls'):
            raise NativeProtocolError('Incomplete or unsupported native completion; no tool will execute.')
        message = choices[0]['message']
        text = message.get('content') or ''
        if not isinstance(text, str):
            raise NativeProtocolError('Only text and client tool calls are supported.')
        if message.get('function_call') is not None:
            raise NativeProtocolError('Legacy function_call responses are not supported.')
        calls = message.get('tool_calls') or []
        if len(calls) > 1:
            raise NativeProtocolError('Multiple native calls are not supported; no tool will execute.')
        if not calls:
            if choices[0]['finish_reason'] == 'tool_calls':
                raise NativeProtocolError('Tool finish reason without a call.')
            return NativeReply(text=text, usage=_usage(response.get('usage')))
        if choices[0]['finish_reason'] != 'tool_calls' or calls[0].get('type') != 'function':
            raise NativeProtocolError('Unsupported or incomplete tool call.')
        item = calls[0]
        function = item['function']
        try:
            args = json.loads(function['arguments'])
        except (ValueError, TypeError) as exc:
            raise NativeProtocolError('Native arguments are not complete JSON.') from exc
        return NativeReply(text, _call(function.get('name'), args, item.get('id')),
                           item['id'], _usage(response.get('usage')))


class AnthropicMessagesAdapter(_Adapter):
    """Anthropic Messages client tool_use/tool_result blocks (non-streaming)."""
    protocol_name = 'anthropic-messages'

    def complete_native(self, messages, schemas):
        system, history = [], []
        for kind, message, result in self._history(messages):
            if message['role'] == 'system':
                system.append(message['content'])
                continue
            if kind == 'pair':
                call = message['_harness_call']
                blocks = ([{'type': 'text', 'text': call['text']}] if call.get('text') else [])
                blocks.append({'type': 'tool_use', 'id': call['id'], 'name': call['name'], 'input': call['args']})
                history.append({'role': 'assistant', 'content': blocks})
                history.append({'role': 'user', 'content': [{'type': 'tool_result', 'tool_use_id': call['id'],
                                'content': result['content'], 'is_error': result['_harness_result']['status'] != 'ok'}]})
            else:
                history.append({'role': message['role'], 'content': [{'type': 'text', 'text': message['content'] or ' '}]})
        merged = []
        for item in history:
            if merged and merged[-1]['role'] == item['role']:
                merged[-1]['content'].extend(item['content'])
            else:
                merged.append(item)
        request = {'model': self.model, 'system': '\n\n'.join(system), 'messages': merged,
                   'max_tokens': self.max_tokens}
        if schemas:
            request.update(tools=[{'name': s['name'], 'description': s['description'],
                                   'input_schema': deepcopy(s['parameters'])} for s in schemas],
                           tool_choice={'type': 'auto', 'disable_parallel_tool_use': True})
        response = _object(self.transport(**request))
        if response.get('stop_reason') not in ('end_turn', 'tool_use'):
            raise NativeProtocolError('Incomplete or unsupported native completion; no tool will execute.')
        blocks = response.get('content', [])
        if any(b.get('type') not in ('text', 'tool_use') for b in blocks):
            raise NativeProtocolError('Only text and client tool_use blocks are supported.')
        calls = [b for b in blocks if b['type'] == 'tool_use']
        text = '\n'.join(b['text'] for b in blocks if b['type'] == 'text')
        if len(calls) > 1:
            raise NativeProtocolError('Multiple native calls are not supported; no tool will execute.')
        if not calls:
            if response['stop_reason'] == 'tool_use':
                raise NativeProtocolError('Tool stop reason without a call.')
            return NativeReply(text=text, usage=_usage(response.get('usage')))
        if response['stop_reason'] != 'tool_use':
            raise NativeProtocolError('Incomplete native tool call.')
        item = calls[0]
        return NativeReply(text, _call(item.get('name'), item.get('input'), item.get('id')),
                           item['id'], _usage(response.get('usage')))

